            pages.extend(range(start, end + 1))
        else:
            pages.append(int(part))
    normalized = []
    for p in pages:
        if p < 1 or p > total:
            raise ValueError(f'page {p} out of range 1..{total}')
        if p not in normalized:
            normalized.append(p)
    return normalized


def load_pdf(path: str) -> PdfReader:
    with open(path, 'rb') as f:
        return PdfReader(f)


def write_pdf(writer: PdfWriter, output: str) -> None:
    with open(output, 'wb') as f:
        writer.write(f)


def split_pdf(input_path: str, output_dir: str, pages_per_file: int) -> None:
    reader = PdfReader(input_path)
    os.makedirs(output_dir, exist_ok=True)
    total = len(reader.pages)
    if pages_per_file <= 0:
        raise ValueError('pages_per_file must be positive')
    index = 1
    for start in range(0, total, pages_per_file):
        writer = PdfWriter()
        for i in range(start, min(start + pages_per_file, total)):
            writer.add_page(reader.pages[i])
        out = os.path.join(output_dir, f'split_{index:03d}.pdf')
        write_pdf(writer, out)
        index += 1


def merge_pdfs(inputs: List[str], output: str) -> None:
    writer = PdfWriter()
    for path in inputs:
        reader = PdfReader(path)
        for page in reader.pages:
            writer.add_page(page)
    write_pdf(writer, output)


def extract_pages(input_path: str, output: str, pages: str) -> None:
    reader = PdfReader(input_path)
    selected = parse_pages(pages, len(reader.pages))
    writer = PdfWriter()
    for page_num in selected:
        writer.add_page(reader.pages[page_num - 1])
    write_pdf(writer, output)


